 courseSubject: "ATLS 5330",
 title: "Wearable Technologies",
 description: "Introduces elements of embedding electronic and computational behaviors into clothing and accoutrements such as watches, handbags, and other wearable accessories. In weekly exercises students build, test, and demonstrate canonical wearable projects. Readings and video viewings survey past and current trends in wearable technologies, including materials, components, fashion and social acceptability. Participants design, develop, debug and document a wearable technology term project. Equivalent - Duplicate Degree Credit Not Granted: ATLS 4330",
