 id: "ATLS-5340",
 courseSubject: "ATLS 5340",
 title: "Experimental Textiles",
 description: "Introduces students to the design and creation of soft interactive objects using textile techniques with a focus on weaving. Specifically, students are guided through exercises intended to cultivate and embodied a sense of textile structures and the mechanical and aesthetic effects they afford. Then, students learn the state of the art of integrating electronics into these soft/deformable textiles structures. With applications from sports, medicine, fashion, architecture, and soft robotics, smart/interactive textiles require a unique set of understandings and design considerations. Students learn about textile structure development, surface design, material sourcing, and electronics integration through project-based assignments. Equivalent - Duplicate Degree Credit Not Granted: ATLS 4340",
