 courseSubject: "ATLS 5400",
 title: "Applied AI Ethics",
 description: "Explores the ethical dimensions of Artificial Intelligence (AI) and its profound impact on individuals and society. Through case studies, hands-on design sprints, engaging discussions, and independent research, students will examine the complex relationship between rapid AI advancements and human values. Through leveraging frameworks from philosophy, behavioral science, computer science, and art, students will critically analyze emerging AI technologies and develop a nuanced understanding of issues like data bias, AI alignment, and the politics of technological systems. Equivalent - Duplicate Degree Credit Not Granted: ATLS 4400",
