 id: "ATLS-6920",
 courseSubject: "ATLS 6920",
 title: "Creative Industries Final Project",
 description: "This course allows MS-CTD students to synthesize what they have learned and test their readiness for a career in the creative technologies and design field. Through this class students work with an academic and/or industry mentor to create a capstone final project emblematic of their focus during their master degree studies. Students learn to propose and scope work, adhere to budget constraints and time schedules, communicate their work, and create a final end deliverable that is presented to the larger ATLAS community. This final project is meant to serve as a culminating portfolio project that helps position students for industry after graduation. Successful completion is required for graduation from the MS-CTD Program.",
