 description: "This course explores how to represent, organize, and reason with knowledge in uncertain environments. Topics covered include logic-based representation (propositional and first-order logic), probabilistic reasoning, Bayesian networks, and decision-making under uncertainty. Students will learn to model intelligent behavior in dynamic domains using structured knowledge and inference techniques. Through theoretical analysis and practical implementation, students explore AI systems that can reason when there is incomplete or ambiguous information.",
