 title: "Computing, Ethics, and Society Foundations",
 description: "Computing systems and technologies fundamentally impact the lives of most people in the world, including how we communicate, get information, socialize, and receive healthcare. This course is the first of a three course sequence that examines ethical issues in the design and implementation of computing systems and technologies, and reflects upon the broad implication of computing on our society. It covers ethical theories, privacy, security, social media, and misinformation.",
