 courseSubject: "CSCA 5312",
 title: "Basic Robotic Behaviors and Odometry",
 description: "Introduction to autonomous mobile robots, including forward kinematics (\u201codometry\u201d), basic sensors and actuator, and simple reactive behavior. The course is centered around two laboratory exercises in the realistic, physics-based simulator \u201cWebots\u201d in which students will experiment with simple reactive behaviors for collision avoidance and line following, state machines, and basic forward kinematics of non-holonomic systems. An overarching objective of this course is to understand the role of the physical system on algorithm design and its role as source of uncertainty that makes robots non-deterministic.",
