 id: "CSCA-5313",
 courseSubject: "CSCA 5313",
 title: "Security and Ethical Hacking: Attacking Unix and Windows",
 description: "This course in the sequence examines attacks on computer systems, with particular attention to Unix Security Model and Windows for memory corruption and binary exploitation. Students can expect to learn about, and apply offensive techniques against, Unix in general. We will demonstrate lateral movement and privilege escalation attacks, as well as buffer overflow and other memory exploitation primitives. Course assessments are through quizzes, hands-on exercises and an exam.",
