 courseSubject: "CSCA 5332",
 title: "Robotic Mapping and Trajectory Generation",
 description: "Building upon the course \u201cBasic Robotic Behaviors and Odometry\u201d, students will learn how to perform basic inverse kinematics of (non-)holonomic systems using a feedback control approach and how to process multi-dimensional sensor signals such as laser range scanners to create discrete representations of the environment (mapping). Also in this course, the overarching focus is mechanisms and sensors as sources of uncertainty and techniques to model and control for them.",
