 courseSubject: "CSCA 5842",
 title: "Deep Learning for Natural Language Processing",
 description: "Deep learning has revolutionized the field of natural language processing and led to many state-of-the-art results. This course introduces students to neural network models and training algorithms frequently used in natural language processing. At the end of this course, learners will be able to explain and implement feedforward networks, recurrent neural networks, convolutional neural networks, and transformers. They will also have an understanding of transfer learning, the paradigm behind popular models such as BERT and GPT-3. Equivalent - Duplicate Degree Credit Not Granted: DTSA 5748",
 credits: "1",
