 id: "CSCA-5844",
 courseSubject: "CSCA 5844",
 title: "Requirement Specifications for Autonomous Systems",
 description: "This course will discuss different ways of formally modeling requirements of interest for autonomous systems. Examples of such requirements include stability, invariance, reachability, regular languages, omega-regular languages, and linear temporal logic properties. In addition, it will introduce non-deterministic finite and b\u00fcchi automata for recognizing, respectively, regular languages and omega-regular languages.",
