 id: "CSCA-5902",
 courseSubject: "CSCA 5902",
 title: "Mastering Classic Reinforcement Learning Algorithms",
 description: "This course introduces the fundamentals of tabular reinforcement learning (RL), with a focus on finite Markov decision processes (MDPs) with scalar rewards. Students will delve into the theoretical foundations of RL, exploring MDP optimization techniques such as value iteration, policy iteration, and linear programming. Additionally, the course covers the optimization of unknown MDPs using tabular RL algorithms like Q-learning, along with their convergence guarantees.",
 credits: "1",
