 id: "CSCA-5912",
 courseSubject: "CSCA 5912",
 title: "Deep Reinforcement Learning: From Theory to Practice",
 description: "This course introduces the fundamental concepts of deep reinforcement learning (RL), combining sampling-based RL optimization with deep neural networks. Topics include function approximation using neural networks, value-function-based methods (e.g., Deep Q-Networks), policy-gradient methods (e.g., REINFORCE), and hybrid approaches such as actor-critic methods. The course covers advanced algorithms like Trust Region Policy Optimization (TRPO), Proximal Policy Optimization (PPO), Deep Deterministic Policy Gradient (DDPG), and Soft Actor-Critic (SAC).",
 credits: "1",
