 title: "Reward Programming: Optimizing RL Efficiency and Safety",
 description: "This course examines the role of reward engineering in reinforcement learning (RL). Students will explore advanced techniques in reward specification, reward elicitation, and reward shaping. Key topics include formal methods such as logic and automata for reward specification, approaches for learning reward functions from demonstrations, and strategies for modifying rewards to enhance learning efficiency and ensure safety.",
