 courseSubject: "CSCI 5030",
 title: "Fundamentals of System Administration and Virtualization",
 description: "Introduces the basic use and administration of Unix and Linux systems. Topics include booting and system management, scripting, storage and logical volume management, filesystem configuration, account management and password security, process control, software installation, event logging and system auditing. Students will also develop familiarity with virtualization platforms such as VirtualBox and VMware to implement and test their system configurations. Equivalent - Duplicate Degree Credit Not Granted: CYBR 5030 CSCI 5113 and CYBR 5113 and CSCI 4113",
