 id: "CSCI-5122",
 courseSubject: "CSCI 5122",
 title: "Neural Networks and Deep Learning for Data Science",
 description: "Explores neural networks and their application to real-world data science and AI problems. Covers neural network theory, algorithms, programming, and applications across various data formats.",
 credits: "3",
