 title: "Algorithms for Whole Genome Sequence Analysis",
 description: "Explore the algorithms that have been developed to assemble and analyze genome sequencing data. Genome sequencing produces vast and complex data that are intractable without efficient algorithms. This course covers the core data structures and algorithms which form the basis for research in topics ranging from evolution to the cause and treatment of many diseases, including cancer. Topics include string matching, indexing, compression, and succinct data structures. No prior knowledge of biology, DNA, or genetics is required.",
