 courseSubject: "CSCI 6254",
 title: "Advanced Data Structures",
 description: "Learn about data structures beyond trees, heaps, and hashtables that are covered in introductory classes on algorithms and data structures. Key topics will include hashtables and their applications, amortized analysis and data structures using amortization, important balanced tree data structures including B-trees, treaps and skip lists, mergeable heaps: binomial and Fibonacci heaps, persistent data structures, tries, suffix tries, suffix automata and spatial data structures.",
