 id: "CSCI-6314",
 courseSubject: "CSCI 6314",
 title: "Algorithmic Economics",
 description: "This course will survey the frontier of algorithmic economics: the study of incentives and strategic behavior through a computational lens. It will show how microeconomic theory applies to the design of algorithms, and conversely, how algorithmic thinking applies to economics. Other topics may include game theory, mechanism design / auction theory, forecasting mechanisms, and voting / social choice theory.",
 credits: "3",
 notes: "(FA24) Student may be dropped from course for non-attendance. The waitlist for this class is automatically re-sequenced to allow first priority to CS PhD students and second priority to CS masters students. Until open enrollment date, registration is restricted to Computer Science graduate students only. Non-CS students can waitlist before that date.",
