 id: "CSCI-6502",
 courseSubject: "CSCI 6502",
 title: "Big Data Analytics: Systems, Algorithms, and Applications",
 description: "This course studies state-of-the-art practice and research on efficient and effective systems and algorithms design for managing and exploring massive amounts of digital data in various application domains. The course takes an integrated approach that studies all three aspects of big data analytics: systems, algorithms, and applications. Specifically, this course covers big data systems for MapReduce, NoSQL, stream processing, deep learning, mobile/wearable/IoT sensing, as well as practical use of indexing, sketching, recommendation, graph, and deep learning algorithms. Domain-specific data management and analysis, such as those in online social networks, scientific discovery, business intelligence, health informatics, urban computing, are also covered.",
 credits: "3",
 notes: "(SP25) Student may be dropped from course for non-attendance. The waitlist for this class is automatically re-sequenced to allow first priority to CS PhD students and second priority to CS masters students. Until open enrollment date, registration is restricted to Computer Science graduate students only. Non-CS students can waitlist before that date.",
 restrictions: "Restricted to graduate students only.",
 offerings: "TBD",
 skills: "MapReduce, NoSQL, stream processing, mobile/wearable/IoT sensing, indexing, sketching, recommendation, graph algorithms, deep learning platforms and algorithms, BDA applications.",
