 courseSubject: "CYBR 5303",
 title: "Cybersecurity Club Companion Course",
 description: "Gives students hands-on experience applying practical security skills and adversarial thinking to real-world problems. Students will work in small teams on internal challenges, lab development, open source contributions, and will represent the university in larger teams for external challenges at the national and global level, such as those hosted by Collegiate Cyber Defense Competition (CCDC), Wicked6, DOE CyberForce, etc. Students will be expected to participate in both internal and external challenges, attend meetings, and present short presentations to the group when appropriate. Previously offered as a special topics course. Equivalent - Duplicate Degree Credit Not Granted: CSCI 5303 and CSCI 4303. Repeatable: Repeatable for up to 3.0 total credit hours.",
