 description: "Focuses on VoIP network design and optimization. The emphasis is on the convergence of VoIP, PSTN and cell phone networks and signaling. Topics include voice processing as well as IP and SS7 signaling. In addition there will be a review of ISDN, DSL, Sonet, ATM, SIP and MPLS. There will be a case problem for sizing a VoIP network using silence suppression. Formerly TLEN 5340.",
