 id: "CYBR-5400",
 courseSubject: "CYBR 5400",
 title: "Principles of Internet Policy",
 description: "Engages in the critical strategic analysis and debate of controversial public policy issues raised by the Internet. Learn how to develop well-reasoned positions on the regulations applied to new Internet-based technologies and business models based on interdisciplinary frameworks that characterize the significant intersection of technology, economics, business, and public policy. Policy topics covered include Broadband as a Universal Service, Net Neutrality, Spectrum Management, Online Privacy, and Cybersecurity.",
 credits: "3",
 notes: "None available (FA24-FA26)",
 restrictions: "",
 offerings: "TBD",
 skills: "Application of Interdisciplinary Policy Framework to evaluate existing public policy and propose new policies. Understanding how National Broadband Plans are used to address the Digital Divide. Internet interconnection and peering arrangements. Achieving open access to the Internet using Net Neutrality regulation Spectrum management tools to lower cost of Internet connectivity GDPR and FTC privacy policies to address impact of Internet tracking technologies on personal privacy. Different cybersecurity frameworks and policies supporting information security on the Internet",
