 title: "Probability Foundations for Data Science and AI",
 description: "Probability Theory covers the foundations of probability and its relationship to statistics and data science. Calculate a probability, independent and dependent outcomes, and conditional events. Understand discrete and continuous random variables and see how this fits with data collection. Learn Gaussian (normal) random variables and the Central Limit Theorem and understand it\u2019s fundamental importance for statistics and data science. Equivalent - Duplicate Degree Credit Not Granted: APPA 5001",
