 description: "This course introduces students to the core principles of neural networks and deep learning, focusing on their application in computer vision. Covering advanced CNN architectures like ResNet, Inception, and DenseNet, along with techniques in object detection (R-CNN, SSD, YOLO) and semantic segmentation (FCN, SegNet, U-Net), this course offers a comprehensive overview of theory and practical skills. Equivalent - Duplicate Degree Credit Not Granted: CSCA 5322",
