 id: "DTSA-5515",
 courseSubject: "DTSA 5515",
 title: "Fair Machine Learning: Foundations",
 description: "This course will introduce students to core ideas in machine learning fairness, including philosophical foundations, basic definitions and distinctions, and on-going debates about how fairness can be defined and operationalized in technical systems. We will define different types of bias and how they are introduced into ML systems. Students will learn about fairness requirements under various regulatory regimes including the GDPR, and types of audits that can be performed to study fairness in existing systems. Equivalent - Duplicate Degree Credit Not Granted: INFA 5101",
