 courseSubject: "DTSA 5516",
 title: "Fair Machine Learning: Algorithms",
 description: "This course will build upon the student\u2019s new foundational knowledge of the space by introducing key technical aspects for implementation of Fair ML. Students will learn how to measure fairness quantitatively, calculate common fairness metrics, implement mitigation algorithms, and test for significance after mitigating for fairness. Students will learn these technical concepts in context of the Machine Learning lifecycle so they are prepared to address fairness via common pre-processing, intrinsic modeling, or post-processing techniques. Equivalent - Duplicate Degree Credit Not Granted: INFA 5102",
