 courseSubject: "DTSA 5705",
 title: "Stability and Capability in Quality Improvement",
 description: "Students will learn to analyze data in terms of process stability and statistical control and why having a stable process is imperative prior to performing statistical hypothesis testing. Students will create statistical process control charts for both continuous and discrete data using R software. Students will analyze data sets for statistical control using control rules based on probability. Additionally, students will learn how to assess a process with respect to how capable it is of meeting specifications, either internal or external, and make decisions about process improvement.",
