 id: "DTSA-5736",
 courseSubject: "DTSA 5736",
 title: "When to Regulate? The Digital Divide and Net Neutrality",
 description: "This is the first of three courses exploring Internet Policy: Principles and Problems, which is part of CU Boulder\u2019s Masters of Science in Data Science and Master of Science in Computer Science programs on Coursera. This course builds an interdisciplinary policy framework to critique and develop regulatory approaches to real-world problems on the Internet. Learners then use the framework to develop a definition of broadband to improve the Digital Divide and to evaluate net neutrality regulations. Equivalent - Duplicate Degree Credit Not Granted: CSCA 5433",
