 id: "DTSA-5737",
 courseSubject: "DTSA 5737",
 title: "Protecting Individual Privacy on the Internet",
 description: "This is the second of three courses exploring Internet Policy: Principles and Problems, which is part of CU Boulder\u2019s Master of Science in Data Science and Master of Science in Computer Science programs on Coursera. This course critiques and develops regulatory approaches to real-world privacy problems created by the Internet. Learners will create a privacy brief based upon the exposure of their own private information when surfing the web. Successful completion of the first course in this series is recommended. Equivalent - Duplicate Degree Credit Not Granted: CSCA 5443",
