 title: "Cybersecurity in Crisis: Information and Internet Security",
 description: "This is the third of three courses exploring Internet Policy: Principles and Problems, which is part of CU Boulder\u2019s Master of Science in Data Science and Master of Science in Computer Science programs on Coursera. This course examines policy approaches to real-world cybersecurity problems occurring on the Internet. Learners will develop a privacy brief on a cybersecurity government policy, law or regulation of their choice. Successful completion of the first course in this series is recommended. Equivalent - Duplicate Degree Credit Not Granted: CSCA 5453",
