 id: "DTSA-5739",
 courseSubject: "DTSA 5739",
 title: "Security and Ethical Hacking: Attacking Web and AI Systems",
 description: "In this last course of the sequence, students will learn how web application and server attacks are conducted against a variety of web technologies and frameworks. In addition, we will introduce the topic of Adversarial Machine Learning and attacks in the Artifical Intelligence domain, including Language Model systems. Students will gain an elementary understanding of the science and techniques behind these attacks, with an appropriate introduction to the AI world. Course assessments are through quizzes, hands-on exercises and an exam. Equivalent - Duplicate Degree Credit Not Granted: CSCA 5323",
