 id: "DTSA-5740",
 courseSubject: "DTSA 5740",
 title: "Global Climate Policies and Analysis",
 description: "This course explores and critically analyzes historical and contemporary climate policies (e.g. Kyoto Protocol and the Paris Agreement). Political issues pertaining to energy sources, such as nuclear energy, will be reviewed. The course will focus on understanding key climate principles and terms surrounding policy development, specifically for low-income or developing countries/communities. Further, this course explores up-to-date technologies that are used in climate analysis. This course also introduces the Python programming language.",
