 id: "DTSA-5741",
 courseSubject: "DTSA 5741",
 title: "Modeling Climate Anomalies with Statistical Analysis",
 description: "This course introduces the use of statistical analysis in Python programming to study and model climate data, specifically with the SciPy and NumPy package. Topics include data visualization, predictive model development, simple linear regression, multivariate linear regression, multivariate linear regression with interaction, and logistic regression. Strong emphasis will be placed on gathering and analyzing climate data with the Python programming language. Recommended: Prerequisite DTSA 5740 - Global Climate Change Policies and Analysis.",
