 id: "DTSA-5742",
 courseSubject: "DTSA 5742",
 title: "Predicting Extreme Climate Behavior with Machine Learning",
 description: "This course reviews current global climate policies with the goal of gathering data and applying machine learning algorithms to predict extreme climate behaviors, specifically in developing countries. Topics include multivariate linear regression, time-series analysis, and numerical weather prediction. The use of monte carlo simulations to forecast extreme weather events will be analyzed. Strong emphasis will be placed on application in the Python programming language. Recommended: Prerequisites DTSA 5740 and DTSA 5741.",
