 id: "DTSA-5745",
 courseSubject: "DTSA 5745",
 title: "Asymmetric Cryptography and Key Management",
 description: "This course will teach the principles of asymmetric cryptography (a.k.a. public-key cryptography) and describe how the key-pair use can enable different security properties/applications. We will study the popular ciphers, e.g., RSA and the Diffie-Hellman Exchange, and learn how/why they work to secure networking, including the mathematical problems anchoring their security. We will learn about the key distribution and management and digital certificates. Required for this course is a working knowledge of discrete mathematics.",
 credits: "1",
 notes: "Only available through CU Boulder on Coursera program offerings. Please refer to the Online Programs section of the catalog for more information.",
 restrictions: "Recommended: Prerequisites DTSA 5743, DTSA 5744.",
