 id: "DTSA-5746",
 courseSubject: "DTSA 5746",
 title: "Cryptographic Hash and Integrity Protection",
 description: "This course describes the cryptographic hash functions and explains their security properties enabling their use for integrity protection. The course will also describe hash chain and Merkle tree. We will study message authenticity and the message authentication code (MAC) based on symmetric keys. Then, we will discuss digital signatures based on asymmetric cryptography, providing security objectives of non-repudiation which were unavailable in the symmetric-cryptography-based MAC.",
 credits: "1",
 notes: "Only available through CU Boulder on Coursera program offerings. Please refer to the Online Programs section of the catalog for more information.",
