 id: "DTSA-5747",
 courseSubject: "DTSA 5747",
 title: "Fundamentals of Natural Language Processing",
 description: "The field of natural language processing aims at getting computers to perform useful and interesting tasks with human language. This course introduces students to the fundamental problems in NLP, the fundamental techniques that are used to solve those problems and lays the foundation for understanding state-of-art methods. At the end of the course, students will be able to implement and analyze text classifiers, sequence labelers, discrete probabilistic models, and vector-based approaches to word meaning. Equivalent - Duplicate Degree Credit Not Granted: CSCA 5832",
 credits: "1",
