 id: "DTSA-5749",
 courseSubject: "DTSA 5749",
 title: "Model and Error Analysis for Natural Language Processing",
 description: "Understanding the performance of natural language processing models goes beyond simply computing measures like accuracy. In this course we will learn methods for analyzing the strengths and weaknesses of NLP systems, both neural and non-neural. We will also learn about problematic biases in NLP data and systems. Methods covered include standard benchmarks, qualitative error analysis, confusion matrices, contrastive and diagnostic evaluation, and probing experiments. Equivalent - Duplicate Degree Credit Not Granted: CSCA 5852",
