 title: "Numerical Methods for Sampling Probability Distributions",
 description: "This course will cover the mathematics and numerical details of using Hamiltonian dynamics and Markov Chain Monte Carlo methods to generate samples from probability distributions. It will cover both sampling of physical systems as well as statistical problems such as sampling the posterior and parameter estimation in Bayesian analysis. Both theory and practical strategies for performing efficient calculations and analyzing their results will be discussed. Exercises and examples will be in Python.",
