 title: "An Introduction to Molecular Simulation Methods and Tools",
 description: "This course will cover the theory and practical approaches to modeling simple molecular systems described by classical physics. It will cover all the fundamentals needed to go from a description of a system at a molecular level through the generation of valid simulation data all the way through analysis of the simulation data to produce useful results. The course will cover the most common open-source simulation programs as well as Python-based analysis tools.",
