 courseSubject: "DTSC 5003",
 title: "Programming for Data Science - Python for Data Science",
 description: "This introductory course will provide Python fundamentals, including data structures and data analysis, complete hands-on exercises throughout the course modules, and create a final project to demonstrate your new skills. This course will demonstrate and practice how to create basic programs, working with data, and solving real-world problems in Python. This course is part of CU Boulder\u2019s Master\u2019s of Science in Data Science and was collaboratively designed by both academics and industry professionals to provide learners with an insider\u2019s perspective on this exciting, evolving, and increasingly vital discipline. This is a Bridge to Data Science Pathway course. Up to 3 hours of bridge courses which meet applicable standards can count toward the 9-credit elective requirement for graduation for students on the Bridge to Data Science Pathway.",
