 id: "DTSC-5302",
 courseSubject: "DTSC 5302",
 title: "Ethical Issues in Data Science",
 description: "This course examines ethical issues related to data science, with the objective of making data science professionals aware of and sensitive to ethical considerations that may arise in their careers. It focuses on ethical frameworks, data science applications that lead to ethical considerations, professional ethics, current media and scholarly articles, and the perspectives and experiences of fellow students and computing professionals.",
 credits: "1",
 notes: "(FA26) This is a special session class with start and end dates that differ from full-semester classes. The corresponding add, drop and withdrawal dates also differ from full-semester classes--please see the special session calendar for specific information: https://www.colorado.edu/registrar/students/cu-boulder-on-coursera. This is a special session class with start and end dates that differ from full-semester classes. The corresponding add, drop and withdrawal dates also differ from full-semester classes--please see the special session calendar for specific information: https://www.colorado.edu/registrar/students/registration/special-sessions. This section is for DTSC majors only. Please petition here if you are not a DTSC major but would like to be considered for enrollment in this course. https://cuboulder.qualtrics.com/jfe/form/SV_cuvjZtMLSemsIUS",
