 id: "ECEN-5313",
 courseSubject: "ECEN 5313",
 title: "Concurrent Programming",
 description: "Introduces the theory and practice of multicore programming. The first part of the course presents foundations of concurrent programming: mutual exclusion, wait-free and lock-free synchronization, spin locks, monitors, memory consistency models. The second part presents a sequence of concurrent data structures and techniques used in their implementations (coarse-grained, fine-grained, optimistic and lock-free synchronization). Equivalent - Duplicate Degree Credit Not Granted: CSCI 5313 and ECEN 4313 and CSCI 4313",
 credits: "3",
